def load_config(defaults: dict, env: dict) -> dict:
    """Return a copy of `defaults` where any env var APP_<KEY> overrides the
    value for key <key> (lowercased), coerced to the type of the default."""
    cfg = dict(defaults)
    prefix = "APP_"
    for env_key, env_val in env.items():
        if env_key.startswith(prefix):
            key = env_key[len(prefix):].lower()
            if key in defaults:
                val_type = type(defaults[key])
                if val_type is bool:
                    # For bool, check common truthy string representations
                    if isinstance(env_val, str):
                        cfg[key] = env_val.lower() in ("1", "true", "yes", "on")
                    else:
                        cfg[key] = bool(env_val)
                else:
                    cfg[key] = val_type(env_val)
    return cfg

